import {visualSlot} from './visual-ui.js';
import {buildExam,examMatrix,examQuestion,submitExam,checkDeadline} from './exams-core.js';
import {chapters,lessons} from './data.js';import {levelNames} from './catalog.js';import {escapeHTML as esc,workedHTML} from './math-ui.js';import {feedbackReason} from './adaptive.js';
export function createExamUI({getState,save,render,src,extraRefs}){
 let config={chapter:-1,count:20,minutes:20,level:'mixed'},newSetup=false,error='';const active=()=>getState().examSession;
 function matrixHTML(e){return `<div class="table-wrap"><table><thead><tr><th>Chương</th><th>Nhận biết</th><th>Hiểu</th><th>Áp dụng</th><th>Phối hợp</th><th>Tổng</th></tr></thead><tbody>${examMatrix(e).filter(x=>x.total).map(r=>`<tr><td>${r.ch+1}</td>${r.levels.map(n=>`<td>${n}</td>`).join('')}<td>${r.total}</td></tr>`).join('')}</tbody></table></div><details><summary>Chủ đề trong ma trận này</summary><ul>${[...new Set(e.items.map(item=>examQuestion(item).topicId))].map(id=>{let qs=e.items.map(examQuestion).filter(q=>q.topicId===id);return `<li>${esc(lessons.find(l=>l.id===id)?.title||id)}: ${qs.length} câu · ${[...new Set(qs.map(q=>levelNames[q.level]))].join(', ')}</li>`}).join('')}</ul></details>`}
 function setup(){let preview=buildExam({...config,now:1,rng:()=>.37});return `<div class="eyebrow">Kỳ thi Chūnin · Tự làm độc lập</div><h1>Kiểm tra đúng phần bạn cần.</h1><section class="panel"><div class="fields"><label>Phạm vi<select data-exam-config="chapter"><option value="-1" ${config.chapter<0?'selected':''}>Tổng hợp 4 chương</option>${chapters.map((c,i)=>`<option value="${i}" ${config.chapter===i?'selected':''}>Chương ${i+1}: ${c.topic}</option>`).join('')}</select></label><label>Số câu (4–40)<input data-exam-config="count" type="number" min="4" max="40" value="${config.count}"></label><label>Thời gian (phút, 0 = không giới hạn)<input data-exam-config="minutes" type="number" min="0" max="180" value="${config.minutes}"></label><label>Mức độ<select data-exam-config="level"><option value="mixed" ${config.level==='mixed'?'selected':''}>Đủ các mức</option><option value="foundation" ${config.level==='foundation'?'selected':''}>Nền tảng</option><option value="advanced" ${config.level==='advanced'?'selected':''}>Vận dụng & phối hợp</option></select></label></div><p>Bài tính yêu cầu nhập đáp án, không có lựa chọn hoặc gợi ý. Có thể quay lại và đánh dấu câu. Chấm sau khi nộp hoặc hết giờ; thời hạn giữ nguyên khi tải lại.</p><h3>Ma trận dự kiến</h3>${matrixHTML(preview)}<p class="muted">Không lặp dạng/biến thể cùng họ. Nếu không đủ dạng phù hợp, dùng ${preview.items.length} câu thay vì thêm câu lặp. Ma trận thực tế hiển thị trong bài thi.</p><div class="actions"><button class="primary" data-start="exam">Bắt đầu kỳ thi</button>${active()&&!active().submitted?'<button class="secondary" data-exam-resume>Tiếp tục kỳ thi đã lưu</button>':''}</div>${error?`<p class="error">${esc(error)}</p>`:''}</section><h2 style="margin-top:24px">Lịch sử</h2>${getState().exams.length?`<div class="table-wrap"><table><tr><th>Ngày</th><th>Số câu</th><th>Điểm</th></tr>${getState().exams.slice(-10).reverse().map(e=>`<tr><td>${new Date(e.date).toLocaleString('vi-VN')}</td><td>${e.count||'—'}</td><td>${e.score}%</td></tr>`).join('')}</table></div>`:'<p class="muted">Chưa có bài thi đã nộp.</p>'}`}
 function html(){let e=active();if(!e||newSetup)return setup();if(checkDeadline(getState(),e)){save()}if(e.submitted)return results(e);let c=e.items[e.index],q=examQuestion(c);return `<div class="quiz-wrap"><div class="quiz-header"><span>Kỳ thi Chūnin · ${e.index+1}/${e.items.length}</span><strong id="exam-timer" role="timer">${timeText(e)}</strong></div><nav class="exam-grid" aria-label="Các câu trong đề">${e.items.map((item,i)=>`<button class="pill ${i===e.index?'active':''}" data-exam-jump="${i}" aria-label="Câu ${i+1}${item.flag?' đã đánh dấu':''}">${i+1}${item.flag?' ⚑':item.choice!==null||item.draft?' ✓':''}</button>`).join('')}</nav><section class="question"><small>Chương ${q.ch+1} · ${levelNames[q.level]} · ${q.sourceLabel}</small><h2>${esc(c.format==='short'?(q.shortPrompt||q.text):q.text)}</h2>${c.format==='short'?`<label>Tự giải toàn bài rồi nhập đáp án<input name="examDraft" autocomplete="off" value="${esc(c.draft)}" placeholder="Có thể dùng dấu ; khi đề hỏi nhiều đại lượng"></label><p class="muted">Không cần gõ lại đơn vị nếu chỉ hỏi một số; đề nhiều đại lượng cần đủ các giá trị theo đúng thứ tự.</p>`:`<div class="options">${c.order.map((orig,i)=>`<button class="option ${c.choice===i?'chosen':''}" data-exam-answer="${i}"><span class="key">${i+1}</span>${esc(q.options[orig])}</button>`).join('')}</div>`}<div class="quiz-actions"><button class="secondary" data-exam-unknown>${c.unknown?'Đã chọn Chưa biết':'Chưa biết'}</button><button class="secondary" data-exam-flag>${c.flag?'Bỏ đánh dấu':'Đánh dấu để quay lại'}</button></div></section><div class="quiz-actions"><button class="secondary" data-exam-move="-1" ${e.index===0?'disabled':''}>Câu trước</button><button class="secondary" data-exam-move="1" ${e.index===e.items.length-1?'disabled':''}>Câu tiếp</button><button class="primary" data-exam-submit>Nộp bài</button></div><details class="panel" style="margin-top:24px"><summary>Ma trận đề đang làm</summary>${matrixHTML(e)}</details><p class="muted">Bản nháp và vị trí được tự lưu. 1–4 chọn đáp án khi không nhập văn bản. Đáp án và lời giải chỉ xuất hiện sau khi nộp.</p></div>`}
 function results(e){let correct=e.results.filter(r=>r.ok).length;return `<section class="reading"><div class="eyebrow">Kết quả kỳ thi</div><h1>${e.timedOut?'Đã nộp khi hết giờ.':'Đã hoàn thành bài thi.'}</h1><div class="score">${Math.round(correct/e.items.length*100)}%</div><p>${correct}/${e.items.length} câu đúng độc lập. Bài này tự biên soạn theo PDF; không phải đề thi chính thức.</p><button class="primary" data-exam-new>Chọn bài thi mới</button>${matrixHTML(e)}<div class="lesson-list" style="margin-top:24px">${e.items.map((item,i)=>{let q=examQuestion(item),result=e.results[i],selected=item.choice===null?-1:item.order[item.choice];return `<article class="panel"><small class="${result.ok?'success':'error'}">Câu ${i+1} · ${result.ok?'Đúng':'Cần ôn'}</small><h3>${esc(q.text)}</h3><p>Bạn trả lời: ${esc(item.unknown?'Chưa biết':item.format==='short'?item.draft:item.choice===null?'Chưa trả lời':q.options[selected])}</p><p><strong>Đáp án: ${esc(q.options[q.correct])}</strong></p><p>${esc(result.ok?q.explain:feedbackReason(q,item.format==='short'?null:selected))}</p>${item.format==='short'&&!result.ok?'<p>Chỉ có đáp số cuối nên chưa thể xác định duy nhất bước sai. Đối chiếu từng bước dưới đây.</p>':''}${visualSlot(q,{key:e.id+':'+i,mode:result.ok?'correct':item.unknown?'unknown':'wrong',selectedText:item.format==='short'?item.draft:selected>=0?q.options[selected]:'',issue:item.format==='short'?null:feedbackReason(q,selected)})}<details><summary>Lời giải và nguồn</summary>${workedHTML(q.worked)}${visualSlot(q,{key:e.id+':'+i+':deep',deep:true,mode:result.ok?'correct':item.unknown?'unknown':'wrong'})}<p>${esc(q.explain)}</p><p class="source">${src(q.ch,q.pages)}${extraRefs(q.supplementary)}</p></details></article>`}).join('')}</div></section>`}
 function timeText(e){if(e.deadline===null)return 'Không giới hạn';let seconds=Math.max(0,Math.ceil((e.deadline-Date.now())/1000));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
 function setChoice(i){let e=active();if(!e||e.submitted)return;e.items[e.index].choice=i;e.items[e.index].unknown=false;save();render()}
 function bind(){document.querySelectorAll('[data-exam-config]').forEach(el=>el.onchange=()=>{let k=el.dataset.examConfig,v=k==='level'?el.value:Number(el.value);if(k==='count'&&(!Number.isInteger(v)||v<4||v>40)||k==='minutes'&&(!Number.isInteger(v)||v<0||v>180)){error='Giữ số câu 4–40 và phút 0–180.';render();return}config[k]=v;error='';render()});let b=document.querySelector('[data-start="exam"]');if(b)b.onclick=()=>{try{if(active()&&!active().submitted&&!confirm('Thay bài thi đang làm bằng đề mới?'))return;getState().examSession=buildExam(config);newSetup=false;save();render()}catch(e){error=e.message;render()}};b=document.querySelector('[data-exam-resume]');if(b)b.onclick=()=>{newSetup=false;render()};b=document.querySelector('[data-exam-new]');if(b)b.onclick=()=>{newSetup=true;render()};document.querySelectorAll('[data-exam-answer]').forEach(b=>b.onclick=()=>setChoice(+b.dataset.examAnswer));document.querySelectorAll('[data-exam-jump]').forEach(b=>b.onclick=()=>{active().index=+b.dataset.examJump;save();render()});document.querySelectorAll('[data-exam-move]').forEach(b=>b.onclick=()=>{let e=active();e.index=Math.max(0,Math.min(e.items.length-1,e.index+Number(b.dataset.examMove)));save();render()});let f=document.querySelector('[name=examDraft]');if(f)f.oninput=()=>{let c=active().items[active().index];c.draft=f.value.slice(0,1000);c.unknown=false;save()};b=document.querySelector('[data-exam-unknown]');if(b)b.onclick=()=>{let c=active().items[active().index];c.unknown=true;c.choice=null;c.draft='';save();render()};b=document.querySelector('[data-exam-flag]');if(b)b.onclick=()=>{let c=active().items[active().index];c.flag=!c.flag;save();render()};b=document.querySelector('[data-exam-submit]');if(b)b.onclick=()=>{let e=active(),unanswered=e.items.filter(c=>c.choice===null&&!c.draft&&!c.unknown).length;if(!confirm(`Nộp bài${unanswered?`, còn ${unanswered} câu chưa trả lời`:''}?`))return;submitExam(getState(),e);save();render()}}
 function keyboard(e){let a=active();if(!a||a.submitted||!document.querySelector('[data-exam-submit]')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.altKey||e.metaKey)return;let c=a.items[a.index];if(/^[1-4]$/.test(e.key)&&c.format==='mcq'){e.preventDefault();setChoice(Number(e.key)-1)}}
 const timer=setInterval(()=>{let e=active();if(!e||e.submitted)return;if(checkDeadline(getState(),e)){save();if(document.querySelector('#exam-timer'))render()}else {let label=document.querySelector('#exam-timer');if(label)label.textContent=timeText(e)}},1000);timer.unref?.();return {html,bind,keyboard,configure:ch=>{config={chapter:ch,count:10,minutes:10,level:'mixed'};newSetup=true},destroy:()=>clearInterval(timer)};
}
